import json
pts=[(0,2),(2,4),(5,0),(6,-3),(8,-3)]
def area(a,b): return (a[1]+b[1])/2*(b[0]-a[0])
cum=[0]
for i in range(4): cum.append(cum[-1]+area(pts[i],pts[i+1]))
xs=[p[0] for p in pts]
best=xs[cum.index(max(cum))]
opts={5:0,2:1,8:2}
print(json.dumps({"computed_key_index":opts[best],"conceptual_only":False,"details":str(cum)}))

