import json
pts=[(0,2),(2,0),(4,-2),(6,0),(8,3)]
def fp(x):
    for (a,b),(c,d) in zip(pts,pts[1:]):
        if a<=x<=c: return b+(d-b)*(x-a)/(c-a)
def slope(x):
    for (a,b),(c,d) in zip(pts,pts[1:]):
        if a<x<c: return (d-b)/(c-a)
sg=lambda v:(v>0)-(v<0)
e=0.01
def ext(x):
    l,r=sg(fp(x-e)),sg(fp(x+e))
    return 'max' if (l,r)==(1,-1) else 'min' if (l,r)==(-1,1) else 'none'
def infl(x): return sg(slope(x-e))!=sg(slope(x+e))
opts=[ext(2)=='max' and infl(4), ext(2)=='min' and ext(6)=='max', infl(2) and ext(6)=='min', ext(4)=='min' and infl(6)]
print(json.dumps({"computed_key_index":opts.index(True),"conceptual_only":False,"details":str(opts)}))
